<?= $this->element('simple_pagination',['page'=>$data['page'],'pages'=>$data['pages']]) ?></section>
<?php if($job->estado==='pronto'): ?><section class="panel mt-3"><div class="d-flex gap-3 mb-3"><?= $this->Form->create(null) ?><?= $this->Form->hidden('acao',['value'=>'todas']) ?><?= $this->Form->button('Selecionar todas as '.($data['counts']['elegivel']??0).' elegíveis',['class'=>'btn btn-outline-primary']) ?><?= $this->Form->end() ?><?= $this->Form->create(null) ?><?= $this->Form->hidden('acao',['value'=>'limpar']) ?><?= $this->Form->button('Limpar seleção inteira',['class'=>'btn btn-light']) ?><?= $this->Form->end() ?></div>
